window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-3ba65a2840d8f42a"]={"versions": [{"id": "FIG-3ba65a2840d8f42a", "releases": ["R1.3.0", "R1.5.1", "R17-03_R1.1.0", "R17-10_R1.2.0", "R18-03_R1.4.0", "R18-10_R4.4.0_R1.5.0", "R19-03", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Architektur- und Datenflussdiagramm mit nummerierter Prozessabfolge. Das Schaubild stellt die grundlegende Erfassung, Filterung und Weiterleitung von Log-Nachrichten aus Anwendungsmodulen über das DLT-Modul (Diagnostic Log and Trace) eines Steuergeräts (ECU) an ein externes Diagnoseterminal dar. Es verortet die Protokollverarbeitung im Kontext der AUTOSAR Classic Platform mit expliziter Laufzeitumgebung (Runtime Environment).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>ECU</strong>: Physisches Steuergerät als Systemgrenze für die lokale Log-Verarbeitung.\n</li><li><strong>Application</strong>: Anwendungssoftwarekomponenten (dreifach dargestellt) innerhalb der ECU.\n</li><li><strong>Runtime Environment</strong>: Zwischenschicht (RTE) zwischen Applikationsebene und Basisfunktionen.\n</li><li><strong>DLT</strong>: Basiskomponente Diagnostic Log and Trace zur Entgegennahme und Filterung von Log-Meldungen.\n</li><li><strong>Externes Gerät (Laptop/Terminal)</strong>: Externe Empfangsstation außerhalb der ECU zur Protokollanzeige und Speicherung.\n</li><li><strong>Schnittstellen / Interaktionen</strong>:\n<ul class=\"fig-list\"><li><code>LogMessage</code> (Schritt 1: <code>Send LogMessage</code>) zwischen Application und DLT.\n</li><li>Ausgehendes Protokoll (Schritt 3: <code>Send DLT LogMessage</code>) zwischen DLT und externem Rechner.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eine Anwendungsinstanz erzeugt eine Protokollmeldung und initiiert das Senden (<code>1 Send LogMessage</code>, gekennzeichnet an der Verbindung <code>LogMessage</code>), geführt durch die Runtime Environment an das DLT-Modul.\n</li><li>Das DLT-Modul filtert die eingegangene Nachricht gemäß Konfiguration bzw. Regelsatz und generiert die standardisierte DLT-Meldung (<code>2 Filter / Generate DLT Message</code>).\n</li><li>Das DLT-Modul überträgt die serialisierte Log-Nachricht über die Steuergerätegrenze hinweg an das externe Logging-Terminal (<code>3 Send DLT LogMessage</code>).\n</li><li>Auf dem externen System wird die empfangene DLT-Nachricht persistiert (<code>4 Store DLT Messages</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt den normativen Standard-Logging-Pfad gemäß PRS Log and Trace Protocol. Für Entwickler verdeutlicht die Abbildung die Entkopplung zwischen der Applikations-Log-Generierung und dem eigentlichen DLT-Meldungsformat: Applikationen liefern unformatierte oder modulspezifische LogMessages ein, während das DLT-Modul Filtermechanismen anwendet, das standardisierte DLT-Header- und Nutzlastformat konstruiert und die Versendung an externe Protokollierungs-Tools steuert.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-4fe9dcc8c995357c", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Architektur- und Datenflussdiagramm mit nummerierter Prozessabfolge. Das Schaubild visualisiert den standardisierten Erfassungs-, Verarbeitungs- und Übertragungspfad von Log-Meldungen auf einem Steuergerät (ECU) über das DLT-Modul an ein externes Diagnoseterminal. Es deckt sowohl Classic AUTOSAR (DLT) als auch die Adaptive Platform (ara::log) ab.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>ECU</strong>: Steuergeräte-Grenze für die fahrzeugseitige Log-Erfassung.\n</li><li><strong>Application</strong>: Anwendungssoftwarekomponenten (dreifach instanziiert).\n</li><li><strong>Dlt module (DLT or ara::log)</strong>: Zentrale Komponente für die Log- und Trace-Funktionalität, wahlweise implementiert über das Classic DLT-Basismodul oder die Adaptive-Plattform-Schnittstelle <code>ara::log</code>.\n</li><li><strong>Externes Terminal (Laptop)</strong>: Externe Auswerte- und Speichereinheit außerhalb des Steuergeräts.\n</li><li><strong>Schnittstellen / Interaktionen</strong>:\n<ul class=\"fig-list\"><li>Lokale Bereitstellung (<code>1 provide log message</code>) von Application an das Dlt module.\n</li><li>Externe Übertragungsstrecke (<code>3 send Dlt message</code>) vom Dlt module zum Terminal.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eine Anwendungsinstanz stellt eine Log-Meldung bereit (<code>1 provide log message</code>), die direkt an das Dlt module übergeben wird.\n</li><li>Das Dlt module filtert die Meldung und generiert eine normgerechte DLT-Meldung (<code>2 filter/generate Dlt message</code>).\n</li><li>Das Dlt module sendet die formatierte DLT-Meldung über die Schnittstelle an das externe Terminal (<code>3 send Dlt message</code>).\n</li><li>Das externe Terminal empfängt und sichert die Meldung dauerhaft (<code>4 store Dlt message</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt den plattformübergreifenden Logging-Ablauf nach PRS Log and Trace Protocol. Für Implementierer ist maßgeblich, dass das DLT-Modul sowohl Classic AUTOSAR (<code>DLT</code>) als auch Adaptive AUTOSAR (<code>ara::log</code>) repräsentiert. Entwickler müssen berücksichtigen, dass Anwendungen unabhängig von der Plattformvariante elementare Log-Nachrichten einliefern, woraufhin die Kapselung, Filterung und Serialisierung in das einheitliche DLT-Format durch das <code>Dlt module</code> erfolgt.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-69e045a7ab7b9a68", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Architektur- und Datenflussdiagramm mit nummerierter Prozessabfolge. Das Schaubild visualisiert den standardisierten Erfassungs-, Verarbeitungs- und Übertragungspfad von Log-Meldungen auf einem Steuergerät (ECU) über das DLT-Modul an ein externes Diagnoseterminal. Es deckt sowohl Classic AUTOSAR (DLT) als auch die Adaptive Platform (ara::log) ab.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>ECU</strong>: Steuergeräte-Grenze für die fahrzeugseitige Log-Erfassung.\n</li><li><strong>Application</strong>: Anwendungssoftwarekomponenten (dreifach instanziiert).\n</li><li><strong>Dlt module (DLT or ara::log)</strong>: Zentrale Komponente für die Log- und Trace-Funktionalität, wahlweise implementiert über das Classic DLT-Basismodul oder die Adaptive-Plattform-Schnittstelle <code>ara::log</code>.\n</li><li><strong>Externes Terminal (Laptop)</strong>: Externe Auswerte- und Speichereinheit außerhalb des Steuergeräts.\n</li><li><strong>Schnittstellen / Interaktionen</strong>:\n<ul class=\"fig-list\"><li>Lokale Bereitstellung (<code>1 provide log message</code>) von Application an das Dlt module.\n</li><li>Externe Übertragungsstrecke (<code>3 send Dlt message</code>) vom Dlt module zum Terminal.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eine Anwendungsinstanz stellt eine Log-Meldung bereit (<code>1 provide log message</code>), die direkt an das Dlt module übergeben wird.\n</li><li>Das Dlt module filtert die Meldung und generiert eine normgerechte DLT-Meldung (<code>2 filter/generate Dlt message</code>).\n</li><li>Das Dlt module sendet die formatierte DLT-Meldung über die Schnittstelle an das externe Terminal (<code>3 send Dlt message</code>).\n</li><li>Das externe Terminal empfängt und sichert die Meldung dauerhaft (<code>4 store Dlt message</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt den plattformübergreifenden Logging-Ablauf nach PRS Log and Trace Protocol. Für Implementierer ist maßgeblich, dass das DLT-Modul sowohl Classic AUTOSAR (<code>DLT</code>) als auch Adaptive AUTOSAR (<code>ara::log</code>) repräsentiert. Entwickler müssen berücksichtigen, dass Anwendungen unabhängig von der Plattformvariante elementare Log-Nachrichten einliefern, woraufhin die Kapselung, Filterung und Serialisierung in das einheitliche DLT-Format durch das <code>Dlt module</code> erfolgt.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-3ba65a2840d8f42a", "to": "FIG-4fe9dcc8c995357c", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Architekturschicht: Der rote Block <code>Runtime Environment</code> innerhalb der <code>ECU</code> wurde entfernt; die Anbindung erfolgt direkt von der Applikation an das DLT-Modul.\n</li><li>Kernkomponente: Die Komponente <code>DLT</code> wurde umbenannt und erweitert zu <code>Dlt module</code> mit dem expliziten Subtitel <code>(DLT or ara::log)</code>, wodurch neben Classic AUTOSAR auch die Adaptive Platform einbezogen wird.\n</li><li>Schritt 1: Interaktion von <code>Send LogMessage</code> / Beschriftung <code>LogMessage</code> am Pfeil geändert zu <code>provide log message</code>.\n</li><li>Schritt 2: Bearbeitungsschritt von <code>Filter / Generate DLT Message</code> (in Sprechblase) geändert zu <code>filter/generate Dlt message</code> (direkt referenziert per Hinweiskreis).\n</li><li>Schritt 3: Interaktion von <code>Send DLT LogMessage</code> geändert zu <code>send Dlt message</code>.\n</li><li>Schritt 4: Senke/Interaktion von <code>Store DLT Messages</code> geändert zu <code>store Dlt message</code>.\n</li></ul>"}, {"from": "FIG-4fe9dcc8c995357c", "to": "FIG-69e045a7ab7b9a68", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
